"""Fill repair_interpretations from Phase 4 — not generated by the LLM."""

from app.modules.llm.schemas.llm_assessment import (
    LLMAssessmentResponse,
    LLMRepairInterpretation,
    TechnicalAlignment,
)
from app.schemas.technical_validation import TechnicalStatus, TechnicalValidationResult

ADVISORY_FROM_TV_MAX = 150


def _clip(text: str, limit: int) -> str:
    text = (text or "").strip()
    if len(text) <= limit:
        return text
    return text[: limit - 1].rstrip() + "…"


def repair_interpretations_from_tv(technical: TechnicalValidationResult) -> list[LLMRepairInterpretation]:
    return [
        LLMRepairInterpretation(
            normalized_operation=a.normalized_operation,
            authoritative_justification_status=a.justification_status,
            advisory_explanation=_clip(a.explanation or "", ADVISORY_FROM_TV_MAX),
        )
        for a in technical.repair_action_assessments
    ]


def enrich_llm_payload_from_tv(data: dict, technical: TechnicalValidationResult) -> dict:
    """Merge authoritative repair rows before schema validation."""
    out = dict(data)
    out["repair_interpretations"] = [
        r.model_dump(mode="json") for r in repair_interpretations_from_tv(technical)
    ]
    if out.get("technical_interpretation") is None:
        out["technical_interpretation"] = {
            "advisory_status": technical.technical_status.value,
            "explanation": "",
        }
    elif isinstance(out["technical_interpretation"], dict):
        ti = dict(out["technical_interpretation"])
        ti.setdefault("advisory_status", technical.technical_status.value)
        out["technical_interpretation"] = ti
    out.setdefault("respects_technical_validation", True)
    out.setdefault("schema_version", "assessment_schema_v2")
    return out


def _alignment_for_tv(status: TechnicalStatus) -> TechnicalAlignment:
    if status == TechnicalStatus.SUPPORTED:
        return TechnicalAlignment.ALIGNED
    if status in (TechnicalStatus.INSUFFICIENT_EVIDENCE, TechnicalStatus.NEEDS_REVIEW):
        return TechnicalAlignment.UNCERTAIN
    return TechnicalAlignment.PARTIALLY_ALIGNED


def build_template_assessment_from_tv(technical: TechnicalValidationResult) -> LLMAssessmentResponse:
    """Deterministic advisory when the gateway returns empty/unparseable JSON."""
    summary = _clip(
        technical.explanation or "See technical validation for the authoritative assessment.",
        280,
    )
    payload = enrich_llm_payload_from_tv(
        {
            "summary": summary,
            "suggested_alignment": _alignment_for_tv(technical.technical_status).value,
            "respects_technical_validation": True,
            "schema_version": "assessment_schema_v2",
            "technical_interpretation": {
                "advisory_status": technical.technical_status.value,
                "explanation": _clip(technical.explanation or "", 150),
            },
        },
        technical,
    )
    return LLMAssessmentResponse.model_validate(payload)
